import { createRoute, z } from '@hono/zod-openapi'

const PostAttachmentsSchema = z
  .object({
    media_keys: z
      .array(z.string())
      .nullable()
      .exactOptional()
      .openapi({ description: 'Media keys of media attached to this Post.' }),
    media_source_tweet_id: z
      .array(z.string())
      .nullable()
      .exactOptional()
      .openapi({ description: 'IDs of the source Posts the attached media originated from.' }),
    poll_ids: z
      .array(z.string())
      .nullable()
      .exactOptional()
      .openapi({ description: 'IDs of polls attached to this Post.' }),
  })
  .openapi({
    description: 'Specifies the type of attachments (if any) present in this Post.',
    required: [],
  })
  .openapi('PostAttachments')

const PostContextAnnotationsSchema = z
  .array(
    z
      .object({
        domain: z
          .xor([
            z
              .object({
                description: z.string().nullable().exactOptional(),
                id: z.string().nullable().exactOptional(),
                name: z.string().nullable().exactOptional(),
              })
              .openapi({
                description: 'A domain or entity referenced by a context annotation.',
                required: [],
              }),
          ])
          .openapi({ description: 'The domain (broad category) this annotation belongs to.' }),
        entity: z
          .xor([
            z
              .object({
                description: z.string().nullable().exactOptional(),
                id: z.string().nullable().exactOptional(),
                name: z.string().nullable().exactOptional(),
              })
              .openapi({
                description: 'A domain or entity referenced by a context annotation.',
                required: [],
              }),
          ])
          .openapi({ description: 'The specific entity recognized within the domain.' }),
      })
      .openapi({
        description: 'A single inferred annotation about the Post (domain and entity context).',
        required: ['domain', 'entity'],
      }),
  )
  .openapi({ description: 'Annotations inferred about the Post (domain and entity context).' })
  .openapi('PostContextAnnotations')

const PostDisplayTextRangeSchema = z
  .array(
    z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
  )
  .length(2)
  .openapi({
    description:
      'The inclusive start and exclusive end indices of the displayable content of the Post.',
  })
  .openapi('PostDisplayTextRange')

const PostEditControlsSchema = z
  .object({
    editable_until: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The time until which this Post can be edited.' }),
    edits_remaining: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description: 'Number of edits still allowed for this Post.',
      }),
    is_edit_eligible: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Indicates whether this Post is eligible to be edited.' }),
  })
  .openapi({
    description: 'Indicates how much longer (if at all) this Post can be edited.',
    required: [],
  })
  .openapi('PostEditControls')

