const CreateBotRequestSchema = z
  .strictObject({
    display_name: z
      .string()
      .min(1)
      .max(50)
      .exactOptional()
      .openapi({ description: "The bot's display name; defaults to the handle." }),
    handle: z
      .string()
      .regex(/^[A-Za-z0-9_]{5,15}$/)
      .min(5)
      .max(15)
      .openapi({
        description:
          "The bot's handle (X screen name): 5-15 characters, letters, numbers, or underscores.",
      }),
    scopes: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          "Scopes for the bot's bearer token. Broadcast moderation additionally supports broadcast.read and broadcast.write. Defaults to the XChat scope set (dm.read, dm.write, tweet.read, users.read, media.write).",
      }),
  })
  .openapi({ required: ['handle'] })
  .openapi('CreateBotRequest')

const CreateBotResponseDataSchema = z
  .object({
    id: z
      .string()
      .regex(/^[0-9]{1,19}$/)
      .openapi({ description: "Unique identifier of the bot's User account." }),
    name: z.string().exactOptional().openapi({ description: "The bot's display name." }),
    scopes: z
      .array(z.string())
      .exactOptional()
      .openapi({ description: "Scopes granted to the bot's bearer token." }),
    token: z
      .string()
      .openapi({
        description: "The bot's bearer token. Returned exactly once; store it securely.",
      }),
    token_expires_at_ms: z
      .int()
      .exactOptional()
      .openapi({ description: "Expiry of the bot's bearer token, in epoch milliseconds." }),
    username: z
      .string()
      .exactOptional()
      .openapi({ description: "The bot's X handle (screen name)." }),
  })
  .openapi({ required: ['id', 'token'] })
  .openapi('CreateBotResponseData')

const CreateBotResponseSchema = z
  .object({
    data: CreateBotResponseDataSchema.exactOptional(),
    errors: z.array(ProblemSchema).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('CreateBotResponse')

const CreateCallRequestSchema = z
  .strictObject({
    audio_only: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Start the call without video.' }),
    conversation_id: z
      .string()
      .regex(/^[A-Za-z0-9:_-]+$/)
      .max(128)
      .exactOptional()
      .openapi({ description: 'XChat conversation to start the call in.' }),
    join_policy: z
      .enum(['open', 'closed', 'trusted'])
      .exactOptional()
      .openapi({
        description:
          "open (default): anyone with the link joins; closed: the host admits each person; trusted: members of the host's Verified Organization join, others ask.",
      }),
    title: z
      .string()
      .max(100)
      .exactOptional()
      .openapi({ description: 'Title shown to participants.' }),
  })
  .openapi({ required: [] })
  .openapi('CreateCallRequest')

const CreateCallResponseDataSchema = z
  .strictObject({
    conversation_id: z
      .string()
      .exactOptional()
      .openapi({ description: 'XChat conversation the call belongs to, if any.' }),
    created_at: z.string().exactOptional().openapi({ description: 'Creation time (RFC 3339).' }),
    host_id: z.string().exactOptional().openapi({ description: "X user id of the call's host." }),
    id: z.string().openapi({ description: 'Unique identifier of the call; also its join secret.' }),
    join_policy: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Who may join: open (anyone with the link), closed (the host admits people), or trusted (the host's Verified Organization).",
      }),
    join_url: z
      .string()
      .exactOptional()
      .openapi({ description: 'Link people open to join the call on X.' }),
    participant_count: z
      .int()
      .exactOptional()
      .openapi({ description: 'People in the call right now.' }),
    title: z.string().exactOptional().openapi({ description: 'Title of the call.' }),
    viewer_may_join: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether the authenticated user may join without asking the host.' }),
  })
  .openapi({ required: ['id'] })
  .openapi('CreateCallResponseData')

const CreateCallResponseSchema = z
  .object({
    data: CreateCallResponseDataSchema.exactOptional(),
    errors: z.array(ProblemSchema).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('CreateCallResponse')

