const CreateChatConversationActionSignaturesSchema = z
  .object({
    encoded_message_event_detail: z
      .string()
      .regex(/^[A-Za-z0-9+\/=_-]+$/)
      .min(1)
      .openapi({ description: 'Base64-encoded message event detail.' }),
    message_event_signature:
      CreateChatConversationActionSignaturesMessageEventSignatureSchema.openapi({
        description: 'Message event signature supplied with an action signature.',
      }),
    message_id: z
      .string()
      .min(1)
      .openapi({ description: 'Client-generated ID of the message being signed.' }),
    signature_payload: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Payload string the client signed; used only in server-side failure logs.',
      }),
  })
  .openapi({ required: ['message_id', 'encoded_message_event_detail', 'message_event_signature'] })
  .openapi('CreateChatConversationActionSignatures')

const CreateChatConversationConversationParticipantKeysSchema = z
  .object({
    encrypted_conversation_key: z
      .string()
      .exactOptional()
      .openapi({ description: "Conversation key encrypted with this participant's public key." }),
    public_key_version: z
      .string()
      .exactOptional()
      .openapi({ description: "Version of the participant's public key used for encryption." }),
    user_id: z.string().exactOptional().openapi({ description: 'Participant user ID.' }),
  })
  .openapi({ required: [] })
  .openapi('CreateChatConversationConversationParticipantKeys')

const CreateChatConversationRequestSchema = z
  .object({
    action_signatures: z
      .array(CreateChatConversationActionSignaturesSchema)
      .exactOptional()
      .openapi({ description: 'Cryptographic signatures for the action.' }),
    base64_encoded_key_rotation: z
      .string()
      .exactOptional()
      .openapi({ description: 'Base64-encoded key rotation payload.' }),
    conversation_id: z.string().openapi({ description: 'Client-generated conversation ID.' }),
    conversation_key_version: z
      .string()
      .openapi({ description: 'Version of the conversation encryption key.' }),
    conversation_participant_keys: z
      .array(CreateChatConversationConversationParticipantKeysSchema)
      .openapi({ description: 'Encrypted conversation keys for each participant.' }),
    group_admins: z
      .array(z.string())
      .exactOptional()
      .openapi({ description: 'User IDs of group admins. Defaults to the creator if omitted.' }),
    group_avatar_url: z
      .string()
      .exactOptional()
      .openapi({ description: 'URL of the avatar image for the group conversation.' }),
    group_description: z
      .string()
      .exactOptional()
      .openapi({ description: 'Description for the group conversation.' }),
    group_members: z
      .array(z.string())
      .openapi({ description: 'User IDs of group members to include in the conversation.' }),
    group_name: z
      .string()
      .exactOptional()
      .openapi({ description: 'Display name for the group conversation.' }),
    ttl_msec: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Message time-to-live in milliseconds. Messages expire after this duration.',
      }),
  })
  .openapi({
    required: [
      'conversation_id',
      'conversation_key_version',
      'conversation_participant_keys',
      'group_members',
    ],
  })
  .openapi('CreateChatConversationRequest')

