const RespondToScheduledCallRequestSchema = z
  .strictObject({
    occurrence_start_time: z
      .string()
      .regex(
        /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])T([01]\d|2[0-3]):[0-5]\d:[0-5]\d(\.\d{1,9})?(Z|[+-]([01]\d|2[0-3]):[0-5]\d)$/,
      )
      .exactOptional()
      .openapi({
        description:
          'Start of the occurrence that scope this or this_and_following refers to (RFC 3339).',
      }),
    response: z
      .enum(['accepted', 'declined', 'tentative'])
      .openapi({ description: 'The answer to the invitation.' }),
    scope: z
      .enum(['all', 'this', 'this_and_following'])
      .exactOptional()
      .openapi({
        description:
          'Which occurrences of a recurring call: all (the default without occurrence_start_time), this (the default with it), or this_and_following.',
      }),
  })
  .openapi({ required: ['response'] })
  .openapi('RespondToScheduledCallRequest')

const RespondToScheduledCallResponseDataSchema = z
  .strictObject({
    response: z
      .string()
      .exactOptional()
      .openapi({ description: 'The answer now on the invitation.' }),
  })
  .openapi({ required: [] })
  .openapi('RespondToScheduledCallResponseData')

const RespondToScheduledCallResponseSchema = z
  .object({
    data: RespondToScheduledCallResponseDataSchema.exactOptional(),
    errors: z.array(ProblemSchema).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('RespondToScheduledCallResponse')

