const ScheduleCallRequestSchema = z
  .strictObject({
    description: z
      .string()
      .max(1000)
      .exactOptional()
      .openapi({ description: 'What the call is about.' }),
    duration_minutes: z
      .int()
      .min(1)
      .max(44640)
      .exactOptional()
      .openapi({
        description: 'How long the call lasts, in minutes. Defaults to 30; at most 31 days.',
      }),
    invitee_ids: z
      .array(z.string().regex(/^[0-9]{1,19}$/))
      .max(25)
      .exactOptional()
      .openapi({ description: 'X user ids of the people to invite.' }),
    notify_invitees: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether invitees get an email about the call. Defaults to true.' }),
    recurrence: z
      .string()
      .max(500)
      .exactOptional()
      .openapi({
        description:
          'RFC 5545 RRULE to repeat the call by, such as FREQ=WEEKLY;BYDAY=MO; the RRULE: prefix is optional.',
      }),
    start_time: z
      .string()
      .regex(
        /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])T([01]\d|2[0-3]):[0-5]\d:[0-5]\d(\.\d{1,9})?(Z|[+-]([01]\d|2[0-3]):[0-5]\d)$/,
      )
      .openapi({ description: 'When the call starts (RFC 3339); not in the past.' }),
    time_zone: z
      .string()
      .max(64)
      .exactOptional()
      .openapi({
        description: 'IANA time zone the recurrence follows, such as America/Los_Angeles.',
      }),
    title: z.string().max(100).exactOptional().openapi({ description: 'Title invitees see.' }),
  })
  .openapi({ required: ['start_time'] })
  .openapi('ScheduleCallRequest')

