export const get2BroadcastsRoute = createRoute({
  method: 'get',
  path: '/2/broadcasts',
  tags: ['Broadcasts'],
  summary: 'List broadcasts',
  description:
    "Returns the authenticated user's live-video broadcasts, or selected owned broadcasts when ids are provided.\n\nAt most one of `ids`, `max_results` may be provided. At most one of `ids`, `pagination_token` may be provided.",
  operationId: 'listBroadcasts',
  request: {
    query: z.object({
      ids: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z
            .array(z.string().regex(/^[a-zA-Z0-9]{1,24}$/))
            .min(1)
            .max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            description: 'Comma-separated broadcast IDs to retrieve instead of listing broadcasts.',
            required: false,
            schema: {
              type: 'array',
              minItems: 1,
              maxItems: 100,
              items: { type: 'string', pattern: '^[a-zA-Z0-9]{1,24}$' },
            },
            explode: false,
            style: 'form',
          },
        }),
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, format: 'int32' },
            style: 'form',
          },
        }),
      pagination_token: z
        .string()
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagination_token',
            in: 'query',
            required: false,
            schema: { type: 'string', minLength: 1 },
            style: 'form',
          },
        }),
      'broadcast.fields': BroadcastFieldsParameterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: ListBroadcastsResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ OAuth2UserToken: ['broadcast.read'] }, { UserToken: [] }],
})

