export const get2CallsScheduledRoute = createRoute({
  method: 'get',
  path: '/2/calls/scheduled',
  tags: ['Calls'],
  summary: 'List scheduled calls',
  description:
    "Returns the X calls on the authenticated user's calendar, earliest first: events on their X Calls calendar, and events on the Microsoft Outlook calendars they linked to X whose conference is an X call. Calls still running at start_time are included. The window defaults to the next 24 hours and may span at most 7 days. Use scheduled_call.fields to select which fields are returned.\n\nWhen both are provided, `start_time` must be earlier than `end_time`.",
  operationId: 'listScheduledCalls',
  request: {
    query: z.object({
      start_time: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'start_time',
            in: 'query',
            description:
              'Calls still running at this time or starting after it (RFC 3339). Defaults to now.',
            required: false,
            schema: { type: 'string', format: 'date-time' },
            style: 'form',
          },
        }),
      end_time: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'end_time',
            in: 'query',
            description:
              'Calls starting before this time (RFC 3339). Defaults to 24 hours after start_time.',
            required: false,
            schema: { type: 'string', format: 'date-time' },
            style: 'form',
          },
        }),
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            description: 'The most calls to return. Defaults to 20.',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, format: 'int32' },
            style: 'form',
          },
        }),
      'scheduled_call.fields': ScheduledCallFieldsParameterParamsSchema,
      expansions: ScheduledCallExpansionsParameterParamsSchema,
      'call.fields': CallFieldsParameterParamsSchema,
      'user.fields': UserFieldsParameterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: ListScheduledCallsResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ OAuth2UserToken: ['calls.read'] }, { UserToken: [] }],
})

