export const post2ChatMediaUploadIdAppendRoute = createRoute({
  method: 'post',
  path: '/2/chat/media/upload/{id}/append',
  tags: ['Chat'],
  summary: 'Append Chat Media Upload',
  description: 'Appends media data to an XChat upload session.',
  externalDocs: { url: 'https://docs.x.com/x-api/media/media-upload' },
  operationId: 'chatMediaUploadAppend',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            schema: { type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/json': { schema: ChatMediaUploadAppendRequestSchema },
        'multipart/form-data': {
          schema: z
            .strictObject({
              conversation_id: z
                .string()
                .openapi({ description: 'The XChat conversation the upload belongs to.' }),
              media: z
                .union([z.file().openapi({ type: 'string', format: 'binary' }), z.string()])
                .openapi({
                  description:
                    'The media segment bytes: base64-encoded in JSON bodies, raw bytes in multipart bodies.',
                }),
              media_hash_key: z
                .string()
                .openapi({ description: 'The media hash key returned by the initialize step.' }),
              segment_index: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(999),
                )
                .openapi({ description: 'The index of this segment in the upload sequence.' }),
            })
            .openapi({ required: ['media', 'segment_index', 'conversation_id', 'media_hash_key'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: ChatMediaUploadAppendResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ OAuth2UserToken: ['media.write'] }, { UserToken: [] }],
})

