export const get2ChatMessageRequestsRoute = createRoute({
  method: 'get',
  path: '/2/chat/message_requests',
  tags: ['Chat'],
  summary: 'Get Chat Message Requests',
  description:
    "Retrieves the authenticated user's pending Chat message requests from one inbox. Message contents are end-to-end encrypted unless the conversation is unencrypted. Accepting or deleting requests between pages can skip or repeat requests, and a page can be empty while `next_token` is set.",
  externalDocs: { url: 'https://developer.x.com/' },
  operationId: 'getChatMessageRequests',
  request: {
    query: z.object({
      inbox_type: z
        .enum(['you_may_know', 'low_quality'])
        .default('you_may_know')
        .exactOptional()
        .openapi({
          param: {
            name: 'inbox_type',
            in: 'query',
            description:
              "Which message request inbox to list: `you_may_know` (the apps' Priority tab) or `low_quality` (the apps' Hidden tab).",
            required: false,
            schema: {
              type: 'string',
              enum: ['you_may_know', 'low_quality'],
              default: 'you_may_know',
            },
            style: 'form',
          },
        }),
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(50),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            description: 'The maximum number of message requests to return.',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 50, format: 'int32', default: 10 },
            style: 'form',
          },
        }),
      pagination_token: z
        .string()
        .regex(/^[0-9]{1,10}$/)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagination_token',
            in: 'query',
            description: 'The next_token from a previous response, to fetch the next page.',
            required: false,
            schema: { type: 'string', pattern: '^[0-9]{1,10}$' },
            style: 'form',
          },
        }),
      'chat_message_request.fields': ChatMessageRequestFieldsParameterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: GetChatMessageRequestsResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ OAuth2UserToken: ['tweet.read', 'users.read', 'dm.read'] }, { UserToken: [] }],
})

