export const get2ConnectionsRoute = createRoute({
  method: 'get',
  path: '/2/connections',
  tags: ['Connections'],
  summary: 'Get Connection History',
  description:
    'Returns active and historical streaming connections with disconnect reasons for the authenticated application.',
  operationId: 'getConnectionHistory',
  request: {
    query: z.object({
      status: z
        .enum(['active', 'inactive', 'all'])
        .default('active')
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['active', 'inactive', 'all'], default: 'active' },
            style: 'form',
          },
        }),
      endpoints: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z
            .array(
              z.enum([
                'filtered_stream',
                'sample_stream',
                'sample10_stream',
                'firehose_stream',
                'tweets_compliance_stream',
                'users_compliance_stream',
                'tweet_label_stream',
                'firehose_stream_lang_en',
                'firehose_stream_lang_ja',
                'firehose_stream_lang_ko',
                'firehose_stream_lang_pt',
                'likes_firehose_stream',
                'likes_sample10_stream',
                'likes_compliance_stream',
              ]),
            )
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'endpoints',
            in: 'query',
            required: false,
            schema: {
              type: 'array',
              uniqueItems: true,
              items: {
                type: 'string',
                enum: [
                  'filtered_stream',
                  'sample_stream',
                  'sample10_stream',
                  'firehose_stream',
                  'tweets_compliance_stream',
                  'users_compliance_stream',
                  'tweet_label_stream',
                  'firehose_stream_lang_en',
                  'firehose_stream_lang_ja',
                  'firehose_stream_lang_ko',
                  'firehose_stream_lang_pt',
                  'likes_firehose_stream',
                  'likes_sample10_stream',
                  'likes_compliance_stream',
                ],
              },
            },
            explode: false,
            style: 'form',
          },
        }),
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, format: 'int32', default: 10 },
            style: 'form',
          },
        }),
      pagination_token: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'pagination_token',
            in: 'query',
            required: false,
            schema: { type: 'string' },
            style: 'form',
          },
        }),
      'connection.fields': ConnectionFieldsParameterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: GetConnectionHistoryResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ BearerToken: [] }],
})

