export const post2MediaUploadIdAppendRoute = createRoute({
  method: 'post',
  path: '/2/media/upload/{id}/append',
  tags: ['Media'],
  summary: 'Append Media Upload',
  operationId: 'appendMediaUpload',
  request: {
    params: z.object({
      id: z
        .string()
        .regex(/^[0-9]{1,19}$/)
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            schema: { type: 'string', pattern: '^[0-9]{1,19}$' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/json': { schema: AppendMediaUploadRequestSchema },
        'multipart/form-data': {
          schema: z
            .strictObject({
              media: z
                .union([z.file().openapi({ type: 'string', format: 'binary' }), z.string()])
                .openapi({ description: 'The media chunk to upload.' }),
              segment_index: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(9999),
                )
                .openapi({ description: 'The index of this segment in the upload sequence.' }),
            })
            .openapi({ required: ['media', 'segment_index'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: AppendMediaUploadResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ OAuth2UserToken: ['media.write'] }, { UserToken: [] }],
})

