export const get2SpacesSearchRoute = createRoute({
  method: 'get',
  path: '/2/spaces/search',
  tags: ['Spaces'],
  summary: 'Search Spaces',
  description: 'Retrieves a list of Spaces matching the specified search query.',
  externalDocs: {
    url: 'https://developer.twitter.com/en/docs/twitter-api/spaces/search/api-reference/get-spaces-search',
  },
  operationId: 'searchSpaces',
  request: {
    query: z.object({
      query: z
        .string()
        .min(1)
        .max(2048)
        .openapi({
          param: {
            name: 'query',
            in: 'query',
            required: true,
            schema: { type: 'string', minLength: 1, maxLength: 2048 },
            style: 'form',
          },
        }),
      state: z
        .enum(['live', 'scheduled', 'all'])
        .default('all')
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['live', 'scheduled', 'all'], default: 'all' },
            style: 'form',
          },
        }),
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, format: 'int32', default: 100 },
            style: 'form',
          },
        }),
      'space.fields': SpaceFieldsParameterParamsSchema,
      expansions: SpaceExpansionsParameterParamsSchema,
      'user.fields': UserFieldsParameterParamsSchema,
      'topic.fields': TopicFieldsParameterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: SearchSpacesResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ OAuth2UserToken: ['users.read', 'tweet.read', 'space.read'] }, { BearerToken: [] }],
})

