export const get2TweetsSearchStreamRulesRoute = createRoute({
  method: 'get',
  path: '/2/tweets/search/stream/rules',
  tags: ['Stream'],
  summary: 'Get filtered-stream rules',
  description:
    'Returns the active filtered-stream rules for the authenticated app. Provide `ids` to fetch specific rules; omit it to list all rules.',
  externalDocs: { url: 'https://docs.x.com/x-api/posts/rules-lookup' },
  operationId: 'getRules',
  request: {
    query: z.object({
      ids: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string().regex(/^[0-9]{1,19}$/)).max(1000),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            required: false,
            schema: {
              type: 'array',
              maxItems: 1000,
              items: { type: 'string', pattern: '^[0-9]{1,19}$' },
            },
            explode: false,
            style: 'form',
          },
        }),
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(1000),
        )
        .default(1000)
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 1000, format: 'int32', default: 1000 },
            style: 'form',
          },
        }),
      pagination_token: z
        .string()
        .length(16)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagination_token',
            in: 'query',
            description: 'A base32hex-encoded pagination token.',
            required: false,
            schema: { type: 'string', minLength: 16, maxLength: 16 },
            style: 'form',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: GetRulesResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ BearerToken: [] }],
})

