export const get2TweetsIdQuoteTweetsRoute = createRoute({
  method: 'get',
  path: '/2/tweets/{id}/quote_tweets',
  tags: ['Posts'],
  summary: 'Get Posts Quoted Posts',
  operationId: 'getPostsQuotedPosts',
  request: {
    params: z.object({
      id: PostIdSchema.openapi({
        param: {
          name: 'id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/PostId' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(10).max(100),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 10, maximum: 100, format: 'int32', default: 10 },
            style: 'form',
          },
        }),
      pagination_token: z
        .string()
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagination_token',
            in: 'query',
            description: 'A base32hex-encoded pagination token.',
            required: false,
            schema: { type: 'string', minLength: 1 },
            style: 'form',
          },
        }),
      exclude: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z
            .array(z.enum(['replies', 'retweets']))
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'exclude',
            in: 'query',
            required: false,
            schema: {
              type: 'array',
              minItems: 1,
              uniqueItems: true,
              items: { type: 'string', enum: ['replies', 'retweets'] },
            },
            explode: false,
            style: 'form',
          },
        }),
      'post.fields': PostFieldsParameterParamsSchema,
      expansions: PostExpansionsParameterParamsSchema,
      'user.fields': UserFieldsParameterParamsSchema,
      'media.fields': MediaFieldsParameterParamsSchema,
      'poll.fields': PollFieldsParameterParamsSchema,
      'place.fields': PlaceFieldsParameterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: GetPostsQuotedPostsResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [
    { OAuth2UserToken: ['tweet.read', 'users.read'] },
    { UserToken: [] },
    { BearerToken: [] },
  ],
})

