export const get2UsersIdTimelinesReverseChronologicalRoute = createRoute({
  method: 'get',
  path: '/2/users/{id}/timelines/reverse_chronological',
  tags: ['Users'],
  summary: 'Get Users Timeline',
  description:
    'When both are provided, `start_time` must be earlier than `end_time`. When both are provided, `since_id` must be less than `until_id`.',
  operationId: 'getUsersTimeline',
  request: {
    params: z.object({
      id: UserIdSchema.openapi({
        param: {
          name: 'id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/UserId' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      max_results: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'max_results',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, format: 'int32' },
            style: 'form',
          },
        }),
      pagination_token: z
        .string()
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagination_token',
            in: 'query',
            description: 'A base32hex-encoded pagination token.',
            required: false,
            schema: { type: 'string', minLength: 1 },
            style: 'form',
          },
        }),
      start_time: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'start_time',
            in: 'query',
            description: 'Must be on or after 2010-11-06.',
            required: false,
            schema: { type: 'string', format: 'date-time' },
            style: 'form',
          },
        }),
      end_time: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'end_time',
            in: 'query',
            description: 'Must be on or after 2010-11-06.',
            required: false,
            schema: { type: 'string', format: 'date-time' },
            style: 'form',
          },
        }),
      since_id: z
        .string()
        .regex(/^[0-9]{1,19}$/)
        .exactOptional()
        .openapi({
          param: {
            name: 'since_id',
            in: 'query',
            required: false,
            schema: { type: 'string', pattern: '^[0-9]{1,19}$' },
            style: 'form',
          },
        }),
      until_id: z
        .string()
        .regex(/^[0-9]{1,19}$/)
        .exactOptional()
        .openapi({
          param: {
            name: 'until_id',
            in: 'query',
            required: false,
            schema: { type: 'string', pattern: '^[0-9]{1,19}$' },
            style: 'form',
          },
        }),
      exclude: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.enum(['replies', 'retweets'])).superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          }),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'exclude',
            in: 'query',
            required: false,
            schema: {
              type: 'array',
              uniqueItems: true,
              items: { type: 'string', enum: ['replies', 'retweets'] },
            },
            explode: false,
            style: 'form',
          },
        }),
      'post.fields': PostFieldsParameterParamsSchema,
      expansions: PostExpansionsParameterParamsSchema,
      'user.fields': UserFieldsParameterParamsSchema,
      'media.fields': MediaFieldsParameterParamsSchema,
      'poll.fields': PollFieldsParameterParamsSchema,
      'place.fields': PlaceFieldsParameterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: { 'application/json': { schema: GetUsersTimelineResponseSchema } },
    },
    default: {
      description: 'The request has failed.',
      content: {
        'application/json': { schema: ErrorSchema },
        'application/problem+json': { schema: ProblemSchema },
      },
    },
  },
  security: [{ OAuth2UserToken: ['users.read', 'tweet.read'] }, { UserToken: [] }],
})

